package com.apexstudio.app.data.engine

import com.arthenica.mobileffmpeg.FFmpeg

/**
 * Foundation engine for FFmpeg operations in ApexStudio.
 *
 * Wraps the mobile-ffmpeg library to provide a Kotlin-friendly API for executing
 * FFmpeg commands, checking availability, and retrieving the library version.
 *
 * Generated by OpenRouter model: nvidia/nemotron-3.5-super-vl:free
 * Fixed and verified by Guard (Muse) — made defensive against missing native lib.
 */
class FFmpegEngine {

    /**
     * Executes an FFmpeg command synchronously.
     *
     * @param command the FFmpeg command line arguments (e.g., `arrayOf("-i", input, output)`)
     * @return the FFmpeg return code. `0` indicates success, `-1` if FFmpeg unavailable.
     */
    fun execute(command: Array<String>): Int {
        return try {
            FFmpeg.execute(command)
        } catch (e: Exception) {
            -1
        }
    }

    /**
     * Returns the version string of the underlying mobile-ffmpeg library.
     *
     * @return version string, or "unknown" if FFmpeg unavailable.
     */
    fun getVersion(): String {
        return try {
            FFmpeg.getVersion()
        } catch (e: Exception) {
            "unknown"
        }
    }

    /**
     * Checks whether FFmpeg is supported on the current device.
     *
     * @return `true` if FFmpeg is available and supported, `false` otherwise.
     */
    fun isAvailable(): Boolean {
        return try {
            // FFmpeg.execute with empty command returns error code if lib loads.
            // A return of 0 or non-zero both mean the lib is present.
            // If it throws, the native lib is missing.
            FFmpeg.getVersion().isNotEmpty()
        } catch (e: Exception) {
            false
        }
    }
}
